insert into public.learning_cards (lesson_id, position, title, blocks) values ('ab6a9950-ab8a-551c-a063-fbfe5c7bc7c2', 1, 'Pas la plus grande ville', '[{"type":"text","text":"Sydney, Toronto, Rio, Istanbul, New York : aucune n’est capitale ! Les capitales sont Canberra, Ottawa, Brasília, Ankara et Washington."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('ab6a9950-ab8a-551c-a063-fbfe5c7bc7c2', 2, 'Une capitale sortie de terre', '[{"type":"keyfigure","value":"1960","label":"Inauguration de Brasília"},{"type":"text","text":"Le Brésil construit une capitale entièrement nouvelle au centre du pays pour remplacer Rio de Janeiro."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('ab6a9950-ab8a-551c-a063-fbfe5c7bc7c2', 3, 'Trois capitales', '[{"type":"text","text":"L’Afrique du Sud en a trois : Pretoria, Le Cap et Bloemfontein. Et la Suisse n’en a officiellement aucune : Berne est la « ville fédérale »."}]'::jsonb);
