insert into public.learning_cards (lesson_id, position, title, blocks) values ('8c36b0b5-7cf4-541a-8218-ccea4ac52679', 1, 'Le toit du monde', '[{"type":"keyfigure","value":"≈ 8 850 m","label":"Altitude de l’Everest, plus haut sommet du monde"},{"type":"text","text":"L’Everest se trouve dans l’Himalaya, à la frontière entre le Népal et la Chine."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('8c36b0b5-7cf4-541a-8218-ccea4ac52679', 2, 'Géants et minuscules', '[{"type":"text","text":"La Russie est le plus grand pays du monde, sur deux continents. Le Vatican, enclavé dans Rome, est le plus petit."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('8c36b0b5-7cf4-541a-8218-ccea4ac52679', 3, 'Eau et sable', '[{"type":"list","items":["Les cinq océans : Pacifique, Atlantique, Indien, Austral, Arctique.","Le Pacifique est le plus grand.","Le Sahara est le plus grand désert chaud du monde."]}]'::jsonb);
