insert into public.learning_cards (lesson_id, position, title, blocks) values ('6805fc4c-aa0a-5aff-83c5-3fda35d9240a', 2, 'Combien de langues ?', '[{"type":"text","text":"La Suisse a quatre langues nationales : allemand, français, italien et romanche. Le Canada est officiellement bilingue. Et au Brésil, on parle portugais, pas espagnol."}]'::jsonb);
