insert into public.learning_cards (lesson_id, position, title, blocks) values ('6a954c42-d040-5e04-ba2c-6c70a6bb707e', 3, 'Un cadeau français', '[{"type":"keyfigure","value":"1886","label":"Inauguration de la statue de la Liberté"},{"type":"text","text":"Bartholdi la sculpte, Gustave Eiffel conçoit sa structure intérieure. La France l’offre aux États-Unis."}]'::jsonb);
